INSERT INTO `box` (`id`, `box`, `heading`, `sub_heading`, `short_desc`, `linktext`, `redirect`, `image`, `publish`) VALUES
(32, 'box1', 'a:1:{s:7:\"English\";s:15:\"Company Profile\";}', 'a:1:{s:7:\"English\";s:32:\"Established in <span>1984</span>\";}', 'a:1:{s:7:\"English\";s:854:\"<div class=\"blueprint_desc\">\r\n<p>Century Paper &amp; Board Mills Limited (CPBM) is the flagship company of the Lakson Group. Since 1984, we have engineered excellence in the packaging industry, establishing ourselves as Pakistan&#39;s market leader through innovation and integrated manufacturing.</p>\r\n\r\n<p>Our 162-acre integrated mill stands as a testament to industrial precision, serving as the preferred strategic partner for global multinationals and national leaders alike.</p>\r\n</div>\r\n\r\n<div class=\"tech_spec_bar\">\r\n<div class=\"spec_item\"><span class=\"label\">ANNUAL OUTPUT</span> <span class=\"value\">280,000 TONS</span></div>\r\n\r\n<div class=\"spec_item\"><span class=\"label\">PLANT AREA</span> <span class=\"value\">162 ACRES</span></div>\r\n\r\n<div class=\"spec_item\"><span class=\"label\">ESTABLISHED</span> <span class=\"value\">1984</span></div>\r\n</div>\r\n\";}', '', 'a:1:{s:7:\"English\";s:0:\"\";}', 'box/2026/07/531-right.jpg', 1),
(33, 'box2', 'a:1:{s:7:\"English\";s:20:\"Strategic Alliances.\";}', '', 'a:1:{s:7:\"English\";s:362:\"<p>We maintain high-value strategic business relationships with leading national and multinational companies in Pakistan and globally across various sectors.</p>\r\n\r\n<p>Our commitment to quality has made us the most preferred supplier for the printing and packaging requirements of major industry players in Food, Beverages, Pharmaceuticals, and Detergents.</p>\r\n\";}', 'a:1:{s:7:\"English\";s:21:\"Learn More About CPBM\";}', 'a:1:{s:7:\"English\";s:0:\"\";}', '', 1),
(34, 'box3', 'a:1:{s:7:\"English\";s:26:\"Food & Beverages Packaging\";}', 'a:1:{s:7:\"English\";s:136:\"Providing specialized packaging solutions for global food giants and local leaders, ensuring food-grade safety and premium presentation.\";}', '', '', 'a:1:{s:7:\"English\";s:0:\"\";}', 'box/2026/07/676-download.jpg', 1),
(35, 'box4', 'a:1:{s:7:\"English\";s:29:\"Pharmaceuticals & Health Care\";}', 'a:1:{s:7:\"English\";s:135:\"High-precision printing boards and packaging for the pharmaceutical industry, meeting stringent quality standards for medical products.\";}', '', '', 'a:1:{s:7:\"English\";s:0:\"\";}', 'box/2026/07/944-download.jpg', 1),
(36, 'box5', 'a:1:{s:7:\"English\";s:27:\"Consumer Goods & Detergents\";}', 'a:1:{s:7:\"English\";s:128:\"Durable and vibrant packaging for household products, soaps, and detergents, designed for shelf-appeal and structural integrity.\";}', '', '', 'a:1:{s:7:\"English\";s:0:\"\";}', 'box/2026/07/768-download.jpg', 1),
(37, 'box6', 'a:1:{s:7:\"English\";s:29:\"Home Appliances & Electronics\";}', 'a:1:{s:7:\"English\";s:126:\"Robust corrugated and board solutions for the transit and display of  appliances, ensuring safe delivery and brand visibility.\";}', '', '', 'a:1:{s:7:\"English\";s:0:\"\";}', 'box/2026/07/561-download.jpg', 1),
(38, 'box7', 'a:1:{s:7:\"English\";s:32:\"<span>Our</span> Core Principles\";}', '', 'a:1:{s:7:\"English\";s:1165:\"<div class=\"Provide-One__wrap\">\r\n<div class=\"Provide-One__left\">\r\n<div class=\"Provide-One__bg\" style=\"background-image: url(webImages/backgrounds/provide-bg.png); \">&nbsp;</div>\r\n\r\n<div class=\"provide-one__sopport\">\r\n<div class=\"provide-one__support-icon\">&nbsp;</div>\r\n\r\n<p class=\"provide-one__support-text\">We&rsquo;re committed to excellence in every process &mdash; from jetty to refinery.</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"Provide-One__right\">\r\n<div class=\"provide-one__bg-shape\"><img alt=\"\" src=\"webImages/shapes/provide-shape-1.png\" /></div>\r\n\r\n<div class=\"Provide-One__content\">\r\n<div class=\"section-title text-left\"><span class=\"section-title__tagline\">Our Strengths</span>\r\n\r\n<h2 class=\"section-title__title\">Consistency, Quality &amp; Reliability</h2>\r\n\r\n<div class=\"section-title__icon\"><img alt=\"\" src=\"webImages/icon/section-title-icon.png\" /></div>\r\n</div>\r\n\r\n<p class=\"Provide-One__text\">For over four decades, Westbury Group have set industry benchmarks in refining, bulk storage, and logistics. Our facilities are built on global standards, ensuring product integrity and dependable operations across every division.</p>\r\n</div>\r\n</div>\r\n</div>\r\n\";}', '', 'a:1:{s:7:\"English\";s:0:\"\";}', '', 1),
(39, 'box8', 'a:1:{s:7:\"English\";s:10:\"Excellence\";}', 'a:1:{s:7:\"English\";s:123:\"Striving incessantly for excellence to sustain our position as a preferred global supplier of  quality paper and packaging.\";}', '', '', 'a:1:{s:7:\"English\";s:0:\"\";}', '', 1),
