(47, 'box15', 'a:1:{s:7:\"English\";s:27:\"Financial Disclosure Portal\";}', '', 'a:1:{s:7:\"English\";s:1510:\"<div class=\"inv-card inv-card--navy\">\r\n				<div class=\"inv-card-icon\"><i class=\"fa-solid fa-calendar-check\"></i></div>\r\n				<h4 class=\"inv-card-title\">Quarterly Reports</h4>\r\n				<p class=\"inv-card-text\">Interim financial results for the first, second, and third quarters as per SECP\r\n					directives.</p>\r\n				<a href=\"#\" class=\"inv-card-link\">Access Archives</a>\r\n			</div>\r\n			<div class=\"inv-card inv-card--gold\">\r\n				<div class=\"inv-card-icon\"><i class=\"fa-solid fa-clock-rotate-left\"></i></div>\r\n				<h4 class=\"inv-card-title\">Half-Yearly Reports</h4>\r\n				<p class=\"inv-card-text\">Reviewed condensed interim financial statements for the six-month period ending\r\n					December.</p>\r\n				<a href=\"#\" class=\"inv-card-link\">Access Archives</a>\r\n			</div>\r\n			<div class=\"inv-card inv-card--green\">\r\n				<div class=\"inv-card-icon\"><i class=\"fa-solid fa-file-contract\"></i></div>\r\n				<h4 class=\"inv-card-title\">Annual Reports</h4>\r\n				<p class=\"inv-card-text\">Complete audited annual financial statements including the Chairmanâ€™s review\r\n					and Directorsâ€™ report.</p>\r\n				<a href=\"#\" class=\"inv-card-link\">Access Archives</a>\r\n			</div>\r\n			<div class=\"inv-card inv-card--red\">\r\n				<div class=\"inv-card-icon\"><i class=\"fa-solid fa-receipt\"></i></div>\r\n				<h4 class=\"inv-card-title\">Financial Data</h4>\r\n				<p class=\"inv-card-text\">Standalone and consolidated financial statements and reporting for regulatory\r\n					compliance.</p>\r\n				<a href=\"#\" class=\"inv-card-link\">Access Data</a>\r\n			</div>\";}', '', 'a:1:{s:7:\"English\";s:0:\"\";}', '', 1),
