INSERT INTO `faqs` (`id`, `title`, `dsc`, `category`, `category_id`, `p_id`, `publish`, `dateTime`) VALUES
(1, 'Does Westbury Group provide end-to-end solutions?', 'Yes, our operations cover every stage &mdash; from vessel handling and bulk storage to refining, distribution, and exports through our Port Qasim facilities.', '', 1, 253, 1, '2025-11-24 10:25:50'),
(2, 'Where are your main facilities located?', 'All major refineries, terminals, and processing plants are based at Port Qasim, Karachi, supported by distribution and export networks nationwide.', '', 1, 253, 1, '2025-11-24 10:26:40'),
(3, 'Are your facilities certified for quality and safety?', 'Absolutely. Our refineries and terminals operate under ISO and HACCP certifications, maintaining international standards of safety and quality control.', '', 1, 253, 1, '2025-11-24 10:27:16'),
(4, 'Does Westbury engage in partnerships or joint ventures?', 'Yes, we have long-standing joint ventures with leading Malaysian firms, bringing world-class technology and expertise to Pakistan&rsquo;s edible oil sector.', '', 1, 253, 1, '2025-11-24 10:27:46');
