INSERT INTO `milestone` (`id`, `heading`, `description`, `year`, `category`, `publish`, `dateTime`) VALUES
(1, 'a:1:{s:7:\"English\";s:18:\"Capacity Expansion\";}', 'a:1:{s:7:\"English\";s:96:\"Enhanced production capacity from 265,000 to 280,000 Metric Tons per annum through BMR projects.\";}', 'a:1:{s:7:\"English\";s:4:\"2025\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:17:43'),
(2, 'a:1:{s:7:\"English\";s:17:\"BMR Modernization\";}', 'a:1:{s:7:\"English\";s:96:\"Enhanced production capacity from 240,000 to 265,000 Metric Tons per annum through BMR projects.\";}', 'a:1:{s:7:\"English\";s:4:\"2021\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:29:04'),
(3, 'a:1:{s:7:\"English\";s:20:\"Box Making Expansion\";}', 'a:1:{s:7:\"English\";s:139:\"Enhanced Box Making capacity to 30,000 Metric Tons per annum after a New Box Machine is added with capacity of 8,000 Metric Tons per annum.\";}', 'a:1:{s:7:\"English\";s:4:\"2011\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:32:19'),
(4, 'a:1:{s:7:\"English\";s:23:\"Corrugator Installation\";}', 'a:1:{s:7:\"English\";s:69:\"Added a new Corrugator with capacity of 24,000 Metric Tons per annum.\";}', 'a:1:{s:7:\"English\";s:4:\"2010\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:32:53'),
(5, 'a:1:{s:7:\"English\";s:17:\"PM-7 Duplex Plant\";}', 'a:1:{s:7:\"English\";s:132:\"Enhanced production capacity to 240,000 Metric Tons per annum as Coated Board Duplex Plant (PM-7) started its commercial operations.\";}', 'a:1:{s:7:\"English\";s:4:\"2009\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:33:17'),
(6, 'a:1:{s:7:\"English\";s:23:\"PM-6 & Coating Facility\";}', 'a:1:{s:7:\"English\";s:173:\"Enhanced production capacity to 110,000 Metric Tons per annum after installation of Paper Machine (PM-6). Added Online Coating facility to three layers Board Machine (PM-4).\";}', 'a:1:{s:7:\"English\";s:4:\"2006\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:33:49'),
(7, 'a:1:{s:7:\"English\";s:15:\"Pulp Processing\";}', 'a:1:{s:7:\"English\";s:56:\"Enhanced un-bleached and bleached straw pulp capacities.\";}', 'a:1:{s:7:\"English\";s:4:\"2005\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:34:07'),
(8, 'a:1:{s:7:\"English\";s:16:\"PM-5 & Box Plant\";}', 'a:1:{s:7:\"English\";s:207:\"Enhanced production capacity to 80,000 Metric Tons per annum after installation of twin layer Board Machine (PM-5). Added a Corrugated Boxes Manufacturing Plant with capacity of 22,000 Metric Tons per annum.\";}', 'a:1:{s:7:\"English\";s:4:\"2003\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:34:33'),
(9, 'a:1:{s:7:\"English\";s:27:\"PM-4 & CM-2 Offline Coating\";}', 'a:1:{s:7:\"English\";s:149:\"Enhanced production capacity to 50,000 Metric Tons through addition of a three layers Board Machine (PM-4).\r\nAdded an Offline Coating Machine (CM-2).\";}', 'a:1:{s:7:\"English\";s:4:\"1997\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:35:00'),
(10, 'a:1:{s:7:\"English\";s:21:\"Commercial Operations\";}', 'a:1:{s:7:\"English\";s:100:\"Commenced commercial production with three machines having capacity of 30,000 Metric Tons per annum.\";}', 'a:1:{s:7:\"English\";s:4:\"1990\";}', 's:10:\"milestones\";', 1, '2026-07-13 11:35:33'),
(11, 'a:1:{s:7:\"English\";s:38:\"Awards, Certifications &amp; Trainings\";}', 'a:1:{s:7:\"English\";s:811:\"<ul>\r\n	<li><strong>CSR Award:</strong> Awarded &quot;18th Corporate Social Responsibility Award 2026&quot; (ESG &amp; Sustainability Leadership) by NFEH (Islamabad, 12 Feb 2026).</li>\r\n	<li><strong>Environment:</strong> Awarded &quot;Environment Excellence Award&quot; by NFEH.</li>\r\n	<li><strong>FSC-CoC:</strong> Certificate Renewal of &quot;FSC-CoC Certification&quot; by SGS.</li>\r\n	<li><strong>ISO Systems:</strong> ISO 9001:2015, ISO 14001:2015, and ISO 45001:2018 Certifications renewed.</li>\r\n	<li><strong>Lab Testing:</strong> ISO/IEC 17025:2017 Certification by PNAC.</li>\r\n	<li><strong>Trainings &amp; Drills:</strong> World Health &amp; Safety Day session, World Environment Day session, safety drills at Karachi &amp; Lahore, FSC-CoC, ISO 45001, and ISO/IEC 17025 trainings conducted.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2026\";}', 's:6:\"awards\";', 1, '2026-07-14 06:47:07'),
(12, 'a:1:{s:7:\"English\";s:38:\"Awards, Certifications &amp; Trainings\";}', 'a:1:{s:7:\"English\";s:637:\"<ul>\r\n	<li><strong>Fire &amp; Safety Award:</strong> 15th Fire and Safety Award by NFEH (Karachi, 04 Nov 2025).</li>\r\n	<li><strong>EHS Award:</strong> 11th Int&#39;l Environment, Health &amp; Safety Award 2025 (Karachi, 11 Sep 2025).</li>\r\n	<li><strong>Quality Week:</strong> Online training session &quot;Quality Way of Excellence&quot; (19 Nov 2025).</li>\r\n	<li><strong>ISO 9001 SME Session:</strong> Online training conducted by NPO Pakistan (18 Dec 2025).</li>\r\n	<li><strong>Other Awards:</strong> Fire Safety Award, CSR Summit Award, Environment Excellence Award, EHS Award, and 39th Corporate Excellence Awards (MAP).</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2025\";}', 's:6:\"awards\";', 1, '2026-07-14 06:47:49'),
(13, 'a:1:{s:7:\"English\";s:20:\"Corporate Excellence\";}', 'a:1:{s:7:\"English\";s:395:\"<ul>\r\n	<li>Awarded &quot;38th Corporate Excellence Award&quot; by MAP.</li>\r\n	<li>Awarded &quot;Best Corporate Award&quot; on Annual Report for the year 2022.</li>\r\n	<li>Awarded &quot;Environment Excellence Award 2024&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Environmental Sustainability Initiative Award 2024&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Fire Safety Award&quot; by NFEH.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2024\";}', 's:6:\"awards\";', 1, '2026-07-14 06:52:11'),
(14, 'a:1:{s:7:\"English\";s:17:\"EHS &amp; Quality\";}', 'a:1:{s:7:\"English\";s:411:\"<ul>\r\n	<li>Awarded 9th International Award on Environment, Health &amp; Safety by The Professional Network.</li>\r\n	<li>Awarded &quot;Environment Excellence Award 2023&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Environmental Sustainability Initiative Award 2023&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Fire Safety Award&quot; by NFEH.</li>\r\n	<li>Awarded Lab Quality System ISO/IEC 17025 Accreditation.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2023\";}', 's:6:\"awards\";', 1, '2026-07-14 06:52:42'),
(15, 'a:1:{s:7:\"English\";s:23:\"Energy &amp; Excellence\";}', 'a:1:{s:7:\"English\";s:280:\"<ul>\r\n	<li>Awarded 10th position in Pakistan Stock Exchange (PSX) Award for Top Companies for the year 2020.</li>\r\n	<li>Awarded &quot;Environment Excellence Award 2022&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Energy Performance Award for Industry 2022&quot; by UNIDO.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2022\";}', 's:6:\"awards\";', 1, '2026-07-14 06:53:12'),
(16, 'a:1:{s:7:\"English\";s:30:\"Sustainability &amp; Packaging\";}', 'a:1:{s:7:\"English\";s:229:\"<ul>\r\n	<li>Awarded &quot;Sustainability Initiative Award 2021&quot; by NFEH.</li>\r\n	<li>Awarded &quot;Best Sustainable Packaging Award&quot; by Future Forum.</li>\r\n	<li>Awarded &quot;Fire Safety Award&quot; by NFEH.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2021\";}', 's:6:\"awards\";', 1, '2026-07-14 06:53:41'),
(17, 'a:1:{s:7:\"English\";s:20:\"FSCâ„¢ Certification\";}', 'a:1:{s:7:\"English\";s:201:\"<ul>\r\n	<li>Awarded &quot;Environment Excellence Award 2020&quot; by NFEH.</li>\r\n	<li>Awarded Forest Stewardship Council&trade; (C165224) - Chain of Custody (FSC&trade;-COC) certification.</li>\r\n</ul>\r\n\";}', 'a:1:{s:7:\"English\";s:4:\"2020\";}', 's:6:\"awards\";', 1, '2026-07-14 06:55:04'),
