<td>15&quot;</td>\r\n			<td>16&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Wrist</strong></td>\r\n			<td>7&quot;</td>\r\n			<td>7.5&quot;</td>\r\n			<td>8&quot;</td>\r\n			<td>8.5&quot;</td>\r\n			<td>9&quot;</td>\r\n			<td>9.5&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Kurta Length</strong></td>\r\n			<td>38&quot;</td>\r\n			<td>39&quot;</td>\r\n			<td>40&quot;</td>\r\n			<td>41&quot;</td>\r\n			<td>42&quot;</td>\r\n			<td>43&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Pant Length</strong></td>\r\n			<td>37&quot;</td>\r\n			<td>38&quot;</td>\r\n			<td>39&quot;</td>\r\n			<td>40&quot;</td>\r\n			<td>41&quot;</td>\r\n			<td>42&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Inseam</strong></td>\r\n			<td>26&quot;</td>\r\n			<td>27&quot;</td>\r\n			<td>28&quot;</td>\r\n			<td>29&quot;</td>\r\n			<td>30&quot;</td>\r\n			<td>31&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Thigh</strong></td>\r\n			<td>21&quot;</td>\r\n			<td>22&quot;</td>\r\n			<td>23&quot;</td>\r\n			<td>24&quot;</td>\r\n			<td>25&quot;</td>\r\n			<td>26&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Calf</strong></td>\r\n			<td>14&quot;</td>\r\n			<td>15&quot;</td>\r\n			<td>16&quot;</td>\r\n			<td>17&quot;</td>\r\n			<td>18&quot;</td>\r\n			<td>19&quot;</td>\r\n		</tr>\r\n		<tr>\r\n			<td><strong>Ankle Opening</strong></td>\r\n			<td>11&quot;</td>\r\n			<td>12&quot;</td>\r\n			<td>13&quot;</td>\r\n			<td>14&quot;</td>\r\n			<td>15&quot;</td>\r\n			<td>16&quot;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\";}'),
