INSERT INTO `product_setting` (`set_id`, `p_id`, `setting_name`, `setting_val`) VALUES
(2386, 161, 'return', 'a:1:{s:7:\"English\";s:7716:\"<h2 data-end=\"148\" data-start=\"116\" style=\"font-weight: normal; line-height: 1.2; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;;\"><strong data-end=\"148\" data-start=\"119\">Shipping &amp; Returns Policy</strong></h2>\r\n\r\n<h3 data-end=\"173\" data-start=\"150\" style=\"font-weight: normal; line-height: 1.2; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;;\"><strong data-end=\"173\" data-start=\"154\">Shipping Policy</strong></h3>\r\n\r\n<p data-end=\"202\" data-start=\"175\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"200\" data-start=\"175\">Order Processing Time</strong></p>\r\n\r\n<ul data-end=\"394\" data-start=\"203\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"289\" data-start=\"203\">\r\n	<p data-end=\"289\" data-start=\"205\">All orders are processed within 1&ndash;3 business days (excluding weekends and holidays).</p>\r\n	</li>\r\n	<li data-end=\"394\" data-start=\"290\">\r\n	<p data-end=\"394\" data-start=\"292\">You will receive an email confirmation once your order has been shipped, along with a tracking number.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"425\" data-start=\"396\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"423\" data-start=\"396\">Domestic Shipping (UAE)</strong></p>\r\n\r\n<ul data-end=\"524\" data-start=\"426\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"466\" data-start=\"426\">\r\n	<p data-end=\"466\" data-start=\"428\">Standard Delivery: 2&ndash;4 business days</p>\r\n	</li>\r\n	<li data-end=\"524\" data-start=\"467\">\r\n	<p data-end=\"524\" data-start=\"469\">Express Delivery: 1&ndash;2 business days (charges may apply)</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"554\" data-start=\"526\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"552\" data-start=\"526\">International Shipping</strong></p>\r\n\r\n<ul data-end=\"726\" data-start=\"555\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"654\" data-start=\"555\">\r\n	<p data-end=\"654\" data-start=\"557\">Available to select countries. Delivery time varies by destination, typically 5&ndash;10 business days.</p>\r\n	</li>\r\n	<li data-end=\"726\" data-start=\"655\">\r\n	<p data-end=\"726\" data-start=\"657\">International customers are responsible for customs duties and taxes.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"750\" data-start=\"728\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"748\" data-start=\"728\">Shipping Charges</strong></p>\r\n\r\n<ul data-end=\"890\" data-start=\"751\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"810\" data-start=\"751\">\r\n	<p data-end=\"810\" data-start=\"753\">Calculated at checkout based on weight and destination.</p>\r\n	</li>\r\n	<li data-end=\"890\" data-start=\"811\">\r\n	<p data-end=\"890\" data-start=\"813\">Free standard shipping on orders above 150 AED&nbsp;</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"895\" data-start=\"892\" style=\"border-right: 0px; border-bottom: 0px; border-left: 0px; border-image: initial; border-top-style: solid; border-top-color: rgb(204, 204, 204); color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\" />\r\n<h3 data-end=\"931\" data-start=\"897\" style=\"font-weight: normal; line-height: 1.2; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;;\"><strong data-end=\"931\" data-start=\"901\">Returns &amp; Exchanges Policy</strong></h3>\r\n\r\n<p data-end=\"970\" data-start=\"933\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"968\" data-start=\"933\">Eligibility for Return/Exchange</strong></p>\r\n\r\n<ul data-end=\"1206\" data-start=\"971\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"1035\" data-start=\"971\">\r\n	<p data-end=\"1035\" data-start=\"973\">We accept returns and exchanges within&nbsp;<strong data-end=\"1022\" data-start=\"1012\">7 days</strong>&nbsp;of delivery.</p>\r\n	</li>\r\n	<li data-end=\"1119\" data-start=\"1036\">\r\n	<p data-end=\"1119\" data-start=\"1038\">Item(s) must be&nbsp;<strong data-end=\"1118\" data-start=\"1054\">unused, unwashed, and in original packaging with tags intact</strong>.</p>\r\n	</li>\r\n	<li data-end=\"1206\" data-start=\"1120\">\r\n	<p data-end=\"1206\" data-start=\"1122\">Sale or discounted items are&nbsp;<strong data-end=\"1165\" data-start=\"1151\">final sale</strong>&nbsp;and not eligible for return or exchange.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1228\" data-start=\"1208\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"1226\" data-start=\"1208\">Return Process&nbsp;</strong><span style=\"text-align: right;\">Once approved, ship the item back to us at your own cost.</span></p>\r\n\r\n<ol data-end=\"1447\" data-start=\"1229\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"1447\" data-start=\"1368\">\r\n	<p data-end=\"1447\" data-start=\"1371\">After receiving and inspecting the item, we will issue a refund or exchange.</p>\r\n	</li>\r\n</ol>\r\n\r\n<p data-end=\"1462\" data-start=\"1449\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"1460\" data-start=\"1449\">Refunds</strong></p>\r\n\r\n<ul data-end=\"1580\" data-start=\"1463\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"1544\" data-start=\"1463\">\r\n	<p data-end=\"1544\" data-start=\"1465\">Refunds are processed to the original payment method within 7&ndash;10 business days.</p>\r\n	</li>\r\n	<li data-end=\"1580\" data-start=\"1545\">\r\n	<p data-end=\"1580\" data-start=\"1547\">Shipping fees are non-refundable.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1596\" data-start=\"1582\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"1594\" data-start=\"1582\">Exchange</strong></p>\r\n\r\n<ul data-end=\"1695\" data-start=\"1597\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"1695\" data-start=\"1597\">\r\n	<p data-end=\"1695\" data-start=\"1599\">If you wish to exchange for another size or item, please contact us first to check availability.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1729\" data-start=\"1697\" style=\"color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\"><strong data-end=\"1727\" data-start=\"1697\">Damaged or Incorrect Items</strong></p>\r\n\r\n<ul data-end=\"1864\" data-start=\"1730\" style=\"padding: 0px 40px; color: rgb(51, 51, 51); font-family: sans-serif, Arial, Verdana, &quot;Trebuchet MS&quot;; font-size: 13px;\">\r\n	<li data-end=\"1864\" data-start=\"1730\">\r\n	<p data-end=\"1864\" data-start=\"1732\">If you receive a damaged or incorrect item, notify us within 48 hours of delivery for a replacement or refund at no additional cost.</p>\r\n	</li>\r\n</ul>\r\n\";}'),
(2387, 161, 'ldesc', 'a:1:{s:7:\"English\";s:1687:\"<p data-end=\"610\" data-start=\"183\">&nbsp;This rich mocha-toned set features a luxurious straight kurta crafted from a textured fabric with subtle gold detailing for a hint of shimmer. The standout elements are the sheer organza sleeves and matching dupatta, both adorned with soft floral prints in rose, sage, and blush tones, adding a delicate contrast.</p>\r\n\r\n<p data-end=\"871\" data-start=\"612\">The tapered trousers are designed with charming tie-up bows and floral fabric accents for a playful, feminine finish. Perfect for semi-formal occasions, intimate gatherings, or festive dinners, this ensemble pairs beautifully with statement jewelry and heels.</p>\r\n\r\n<p data-end=\"888\" data-start=\"873\"><strong data-end=\"886\" data-start=\"873\">Includes:</strong></p>\r\n\r\n<ul data-end=\"1015\" data-start=\"889\">\r\n	<li data-end=\"933\" data-start=\"889\">\r\n	<p data-end=\"933\" data-start=\"891\">Textured kurta with sheer floral sleeves</p>\r\n	</li>\r\n	<li data-end=\"989\" data-start=\"934\">\r\n	<p data-end=\"989\" data-start=\"936\">Tapered trousers with side ties and printed accents</p>\r\n	</li>\r\n	<li data-end=\"1015\" data-start=\"990\">\r\n	<p data-end=\"1015\" data-start=\"992\">Printed organza dupatta</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1230\" data-start=\"1017\"><strong data-end=\"1027\" data-start=\"1017\">Color:</strong> Mocha Brown with Multicolor Floral Accents<br data-end=\"1073\" data-start=\"1070\" />\r\n<strong data-end=\"1084\" data-start=\"1073\">Fabric:</strong> Kurta &amp; Pants &ndash; Premium Silk Blend | Dupatta &ndash; Organza<br data-end=\"1142\" data-start=\"1139\" />\r\n<strong data-end=\"1156\" data-start=\"1142\">Style Tip:</strong> Pair with bold earrings and strappy heels for a contemporary ethnic look.</p>\r\n\";}'),
