(2507, 245, 'ldesc', 'a:1:{s:7:\"English\";s:733:\"<p><strong>High-Quality Plastic &amp; Streamlined Shape:</strong> Made of ultra-high quality plastic; comfortable to hold and easy to clean.</p>\r\n\r\n<p><strong>Soft &amp; Elastic Teat:</strong> Encourages natural tongue movement and effortless sucking.</p>\r\n\r\n<p><strong>Perfect Nipple Shape:</strong> Provides a natural feel, easier latching, and helps prevent colic.</p>\r\n\r\n<p><strong>Air Ventilation System:</strong> Controls air pressure in the bottle, minimizing extra air intake.</p>\r\n\r\n<p><strong>BPA/BPS-Free:</strong> Safe and healthy for babies.</p>\r\n\r\n<p><strong>Sterilization Method:</strong> Boiling and Microwave.</p>\r\n\r\n<p><strong>Environment Friendly:</strong> Designed with care for all beings, not just humans.</p>\r\n\";}'),
(2508, 245, 'size_chart', 'a:1:{s:7:\"English\";s:344:\"<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\">\r\n	<thead>\r\n		<tr>\r\n			<th>Size</th>\r\n			<th>Capacity</th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>50 ml</td>\r\n			<td>50 ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>120 ml</td>\r\n			<td>120 ml</td>\r\n		</tr>\r\n		<tr>\r\n			<td>250 ml / 8 oz</td>\r\n			<td>250 ml (8 oz)</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\";}'),
