INSERT INTO `temp` (`id`, `name`, `value`, `dateTime`) VALUES
(9859, 'Query', 'SELECT `procat_prodet_id`,`prodet_id`  FROM `product_category` JOIN `proudct_detail` as detail on \r\n        `product_category`.`procat_prodet_id` = `detail`.`prodet_id` WHERE ( `product_category`.`procat_cat_id` LIKE \'%,33,%\' )  AND `product_discount_20` > 0  GROUP BY \r\n        `detail`.`prodet_id`  ORDER BY sort ASC', '2025-11-14 03:44:11'),
